sql_query:
SELECT DISTINCT risk_tolerance
            FROM ATOM_ENTITY_INVESTOR_PROFILE_001
            WHERE risk_tolerance IS NOT NULL AND TRIM(risk_tolerance) <> '';

SELECT DISTINCT time_horizon
            FROM ATOM_ENTITY_INVESTOR_PROFILE_001
            WHERE time_horizon IS NOT NULL AND TRIM(time_horizon) <> '';

SELECT investor_id, investor_name
            FROM ATOM_ENTITY_INVESTOR_PROFILE_001
            WHERE sector_focus IS NULL OR TRIM(sector_focus) = '';

SELECT investment_type, COUNT(*) AS holding_count
            FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001
            GROUP BY investment_type;
